//! Bounded thread-safe LRU cache with TTL.
//!
//! Public API:
//! - `Cache<K, V>`: A generic LRU cache with TTL, thread-safe via Arc<Mutex<...>>.
//! - `Cache::new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
//! - `Cache::get(&self, key: &K) -> Option<V>`
//! - `Cache::insert(&self, key: K, value: V)`
//! - `Cache::remove(&self, key: &K) -> Option<V>`
//! - `Cache::len(&self) -> usize`
//! - `Clock` trait: `now() -> Instant`
//! - `SystemClock`: uses std::time::Instant::now()
//! - `TestClock`: deterministic clock for tests, with `advance(Duration)`
//!
//! Edge cases handled:
//! - Zero capacity: insert is a no-op, get returns None, len is 0.
//! - Negative capacity: not possible in Rust (usize), but zero is handled.
//! - TTL expiry: entries are considered expired if now - inserted_at >= ttl.
//! - LRU eviction: when capacity is reached, least recently used entry is evicted.
//! - Concurrent access: safe via Mutex.
//! - Repeated remove: returns None if key not present.
//! - Insert over existing key: updates value and refreshes TTL and LRU position.
//! - Get on expired entry: returns None and removes the entry.
//! - Clock injection: TestClock allows deterministic time control.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for a clock that can provide the current time.
pub trait Clock: Send + Sync {
    fn now(&self) -> Instant;
}

/// System clock using std::time::Instant.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// Deterministic clock for testing.
pub struct TestClock {
    inner: Mutex<Instant>,
}

impl TestClock {
    /// Create a new TestClock starting at the given instant.
    pub fn new(start: Instant) -> Self {
        TestClock {
            inner: Mutex::new(start),
        }
    }

    /// Advance the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for TestClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

/// Internal entry stored in the cache.
struct Entry<V> {
    value: V,
    inserted_at: Instant,
}

/// Internal LRU list node. We use a Vec-based approach with indices for simplicity,
/// but a proper doubly-linked list would be more efficient. For clarity and correctness,
/// we use a HashMap for O(1) lookup and a Vec for LRU ordering (front = most recent, back = least recent).
/// However, moving elements in a Vec is O(n). For a bounded cache with reasonable capacity,
/// this is acceptable. For production, a linked list would be better.
