/// Alternative: use a HashMap<K, (V, Instant, usize)> and a Vec<K> for LRU order.
/// We'll use a simpler approach: HashMap for storage, and a Vec for LRU order.
/// When an entry is accessed or inserted, we move it to the front of the LRU list.
/// When evicting, we remove from the back.

/// A bounded thread-safe LRU cache with TTL.
pub struct Cache<K, V>
where
    K: std::hash::Hash + Eq + Clone + Send + 'static,
    V: Clone + Send + 'static,
