// ErrPoolClosed is returned when submitting to a closed pool.
var ErrPoolClosed = errors.New("workerpool: pool is closed")

// ErrContextCanceled is returned when the context is canceled during submission.
var ErrContextCanceled = errors.New("workerpool: context canceled")

// Pool is a bounded worker pool.
type Pool struct {
	queue     chan func()
	workers   int
	capacity  int

	// shutdownOnce ensures Shutdown is idempotent.
	shutdownOnce sync.Once
	// closed is set when Shutdown is called.
	closed atomic.Bool

	// wg tracks active workers.
	wg sync.WaitGroup

	// counters
	mu        sync.Mutex
	submitted int
	completed int
	panicked  int
	rejected  int
}

// NewPool creates a new worker pool.
// capacity: maximum number of tasks that can be queued (backpressure).
// workers: number of worker goroutines.
// Panics if workers < 1 or capacity < 0.
func NewPool(capacity int, workers int) *Pool {
	if workers < 1 {
		panic("workerpool: workers must be >= 1")
	}
	if capacity < 0 {
		panic("workerpool: capacity must be >= 0")
	}
	p := &Pool{
		queue:    make(chan func(), capacity),
		workers:  workers,
		capacity: capacity,
	}
	p.wg.Add(workers)
	for i := 0; i < workers; i++ {
		go p.worker()
	}
	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()
	for task := range p.queue {
		p.runTask(task)
	}
}

