//! Bounded thread-safe LRU cache with TTL using only the Rust standard library.
//!
//! # Public API
//!
//! - `Cache<K, V>`: A thread-safe LRU cache with TTL support.
//!   - `new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
//!   - `get(&self, key: &K) -> Option<V>`
//!   - `insert(&self, key: K, value: V)`
//!   - `remove(&self, key: &K) -> Option<V>`
//!   - `len(&self) -> usize`
//!   - `clear(&self)`
//!
//! - `Clock`: A trait for injectable time sources.
//!   - `now(&self) -> Instant`
//!
//! - `SystemClock`: A clock that uses `std::time::Instant::now()`.
//!
//! - `TestClock`: A deterministic clock for testing, allowing manual time advancement.
//!
//! # Ownership Choices
//!
//! - `Arc<Cache<K, V>>` is used for shared ownership across threads.
//! - `Mutex<CacheInner<K, V>>` protects the internal state (HashMap + LRU list).
//! - Keys and values are owned by the cache. `get` returns a clone of the value.
//! - The clock is shared via `Arc<dyn Clock>` to allow injection for tests.
//!
//! # Concurrency Invariants
//!
//! - All mutations and reads go through the `Mutex`, ensuring exclusive access.
//! - TTL checks are performed on `get` and lazily on eviction.
//! - LRU order is maintained by moving accessed/inserted entries to the front.
//! - Eviction removes the least recently used entry when capacity is exceeded.

use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// A trait for injectable time sources.
pub trait Clock: Send + Sync {
    /// Returns the current time.
    fn now(&self) -> Instant;
}

/// A clock that uses the system time.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// A deterministic clock for testing, allowing manual time advancement.
pub struct TestClock {
    inner: Mutex<Instant>,
}

impl TestClock {
    /// Creates a new `TestClock` starting at the given instant.
    pub fn new(start: Instant) -> Self {
        TestClock {
            inner: Mutex::new(start),
        }
    }

    /// Advances the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for TestClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

/// Internal entry stored in the cache.
struct Entry<V> {
    value: V,
    inserted_at: Instant,
}

/// Internal state of the cache, protected by a Mutex.
struct CacheInner<K, V> {
    map: HashMap<K, Entry<V>>,
    lru_order: VecDeque<K>,
    capacity: usize,
    ttl: Duration,
    clock: Arc<dyn Clock>,
}

impl<K, V> CacheInner<K, V>
where
    K: Clone + Eq + std::hash::Hash,
    V: Clone,
{
    fn new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self {
        CacheInner {
            map: HashMap::new(),
            lru_order: VecDeque::new(),
            capacity,
            ttl,
            clock,
        }
    }

    /// Removes expired entries from the map and LRU order.
    /// Returns the number of entries removed.
    fn remove_expired(&mut self) -> usize {
        let now = self.clock.now();
        let mut to_remove = Vec::new();
        for (key, entry) in &self.map {
            if now.duration_since(entry.inserted_at) >= self.ttl {
                to_remove.push(key.clone());
            }
        }
        let count = to_remove.len();
        for key in to_remove {
            self.map.remove(&key);
            // Remove from LRU order
            if let Some(pos) = self.lru_order.iter().position(|k| k == &key) {
                self.lru_order.remove(pos);
            }
        }
        count
    }

    /// Gets a value from the cache, updating LRU order if found and not expired.
    fn get(&mut self, key: &K) -> Option<V> {
        // Check if the key exists and is not expired
        if let Some(entry) = self.map.get(key) {
            let now = self.clock.now();
            if now.duration_since(entry.inserted_at) >= self.ttl {
                // Expired: remove it
                self.map.remove(key);
                if let Some(pos) = self.lru_order.iter().position(|k| k == key) {
                    self.lru_order.remove(pos);
                }
                return None;
            }
            // Move to front of LRU order
            if let Some(pos) = self.lru_order.iter().position(|k| k == key) {
                self.lru_order.remove(pos);
            }
            self.lru_order.push_front(key.clone());
            return Some(entry.value.clone());
        }
        None
    }

    /// Inserts a key-value pair into the cache, evicting LRU if necessary.
    fn insert(&mut self, key: K, value: V) {
        let now = self.clock.now();
