        if self.map.contains_key(&key) {
            self.map.insert(key.clone(), entry);
            if let Some(pos) = self.lru_order.iter().position(|k| k == &key) {
                self.lru_order.remove(pos);
            }
            self.lru_order.push_front(key);
            return;
