/**
 * Strongly typed bounded asynchronous work queue.
 *
 * Public API:
 * - class AsyncWorkQueue<T, R>
 *   - constructor(options: AsyncWorkQueueOptions<T, R>)
 *   - enqueue(task: T): Promise<R>
 *   - close(): Promise<void>
 *   - get pendingCount(): number
 *   - get runningCount(): number
 *   - get capacity(): number
 *
 * Options:
 * - concurrency: number (default 1) - max concurrent running tasks
 * - capacity: number (default Infinity) - max pending + running tasks (backpressure)
 * - signal?: AbortSignal - external cancellation signal
 * - onError?: (error: unknown, task: T) => void - optional error handler
 *
 * Behavior:
 * - enqueue() returns a Promise that resolves with the task result or rejects with the error.
 * - If the queue is at capacity, enqueue() waits until space is available (backpressure).
 * - If the queue is closed, enqueue() rejects with a ClosedError.
 * - If the AbortSignal is aborted, pending tasks are rejected with AbortError, and running tasks
 *   are signaled via an internal AbortController.
 * - close() stops accepting new tasks, waits for running tasks to complete, and rejects all
 *   pending tasks with a ClosedError.
 * - Cancellation distinguishes between pending (not yet started) and running (already started) tasks.
 *   Pending tasks are rejected immediately upon cancellation. Running tasks receive an abort signal
 *   and are expected to cooperate; if they don't, they will still complete but their results are
 *   discarded if the task was canceled before completion.
 *
 * Edge cases handled:
 * - Zero or negative capacity: treated as Infinity (unbounded).
 * - Repeated close(): idempotent, subsequent calls are no-ops.
 * - Loader/task failures: errors are propagated to the caller's promise.
 * - Canceled waiters: pending tasks rejected with AbortError.
 * - Resources released during cleanup: all internal state is cleared on close.
 */

// --- Type Definitions ---

export interface AsyncWorkQueueOptions<T, R> {
  concurrency?: number;
  capacity?: number;
  signal?: AbortSignal;
  onError?: (error: unknown, task: T) => void;
}

export class ClosedError extends Error {
  constructor(message = "Queue is closed") {
    super(message);
    this.name = "ClosedError";
  }
}

export class AbortError extends Error {
  constructor(message = "Task was aborted") {
    super(message);
    this.name = "AbortError";
  }
}

interface TaskEntry<T, R> {
  task: T;
  resolve: (value: R) => void;
  reject: (reason: unknown) => void;
  abortController: AbortController;
  status: "pending" | "running" | "completed" | "canceled";
  started: boolean;
}

// --- Implementation ---

export class AsyncWorkQueue<T, R> {
  private readonly concurrency: number;
  private readonly capacity: number;
  private readonly signal?: AbortSignal;
  private readonly onError?: (error: unknown, task: T) => void;

  private pending: TaskEntry<T, R>[] = [];
  private running: TaskEntry<T, R>[] = [];
  private closed: boolean = false;
  private closedPromise: Promise<void> | null = null;
  private closedResolve: (() => void) | null = null;
  private externalAbortListener: (() => void) | null = null;

  constructor(options: AsyncWorkQueueOptions<T, R> = {}) {
    const { concurrency = 1, capacity = Infinity, signal, onError } = options;

    // Normalize concurrency: at least 1
    this.concurrency = Math.max(1, Math.floor(concurrency));

    // Normalize capacity: zero or negative means unbounded
    this.capacity = capacity <= 0 ? Infinity : Math.floor(capacity);

    this.signal = signal;
    this.onError = onError;

    if (this.signal) {
      this.externalAbortListener = () => {
