// Package workerpool provides a bounded worker pool with context cancellation,
// task submission with backpressure, panic recovery, graceful shutdown, and
// deterministic result delivery.
//
// Public API:
//
//   - NewPool(capacity int, workers int) *Pool
//     Creates a new pool with the given queue capacity and number of workers.
//     capacity must be >= 0; workers must be >= 1.
//
//   - (*Pool).Submit(ctx context.Context, task func() (interface{}, error)) error
//     Submits a task to the pool. Returns an error if the pool is closed or
//     if the context is canceled before the task can be enqueued.
//     If the queue is full, Submit blocks until space is available or ctx is canceled.
//
//   - (*Pool).Shutdown()
//     Initiates graceful shutdown: no new tasks are accepted, but already
//     queued tasks are processed. After all queued tasks complete, workers exit.
//     Safe to call multiple times.
//
//   - (*Pool).Wait()
//     Blocks until all workers have exited and all queued tasks have completed.
//     Must be called after Shutdown to ensure clean termination.
//
//   - (*Pool).Stats() (submitted, completed, failed, panicked int)
//     Returns counters for tasks submitted, completed successfully, failed with
//     error, and panicked.
//
// Concurrency invariants:
//   - The queue is a buffered channel; capacity controls backpressure.
//   - Workers pull from the queue and execute tasks, recovering panics.
//   - Shutdown closes the queue channel; workers drain remaining tasks then exit.
//   - Wait waits for all workers to finish via a WaitGroup.
//   - No goroutine leaks: all workers exit after queue is closed and drained.
//   - Data races avoided via channel synchronization and atomic counters.
package workerpool

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
)

// ErrPoolClosed is returned when submitting to a closed pool.
var ErrPoolClosed = errors.New("workerpool: pool is closed")

// ErrContextCanceled is returned when the context is canceled before submission.
var ErrContextCanceled = errors.New("workerpool: context canceled")

// task represents a unit of work to be executed by a worker.
type task struct {
	fn     func() (interface{}, error)
	result chan<- result
}

// result holds the outcome of a task execution.
type result struct {
	value interface{}
	err   error
}

// Pool is a bounded worker pool.
type Pool struct {
	queue     chan task
	workers   int
	capacity  int
	wg        sync.WaitGroup
	closeOnce sync.Once
	closed    atomic.Bool

	// Counters (atomic for lock-free reads)
	submitted  atomic.Int64
	completed  atomic.Int64
	failed     atomic.Int64
	panicked   atomic.Int64
}

// NewPool creates a new worker pool.
// capacity is the maximum number of queued tasks (backpressure limit).
// workers is the number of concurrent worker goroutines.
// capacity must be >= 0, workers must be >= 1.
func NewPool(capacity int, workers int) *Pool {
	if capacity < 0 {
		capacity = 0
	}
	if workers < 1 {
		workers = 1
	}
	p := &Pool{
		queue:    make(chan task, capacity),
		workers:  workers,
		capacity: capacity,
	}
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}
	return p
}

// worker is the main loop for each worker goroutine.
// It reads tasks from the queue, executes them with panic recovery, and
// delivers results. It exits when the queue is closed and drained.
func (p *Pool) worker() {
	defer p.wg.Done()
	for t := range p.queue {
		p.executeTask(t)
	}
}

// executeTask runs the task function, recovering any panic, and sends the
// result to the result channel.
func (p *Pool) executeTask(t task) {
	defer func() {
		if r := recover(); r != nil {
			p.panicked.Add(1)
			// Convert panic to error
			err := errors.New("panic in task")
			if errStr, ok := r.(string); ok {
				err = errors.New(errStr)
			} else if errObj, ok := r.(error); ok {
				err = errObj
			}
			t.result <- result{value: nil, err: err}
		}
	}()

	p.submitted.Add(1)
	val, err := t.fn()
	if err != nil {
		p.failed.Add(1)
	} else {
		p.completed.Add(1)
	}
	t.result <- result{value: val, err: err}
}

// Submit submits a task to the pool.
// If the pool is closed, returns ErrPoolClosed.
// If ctx is canceled before the task is enqueued, returns ErrContextCanceled.
// If the queue is full, blocks until space is available or ctx is canceled.
func (p *Pool) Submit(ctx context.Context, fn func() (interface{}, error)) error {
	if p.closed.Load() {
		return ErrPoolClosed
	}

	// Check context before attempting to send
	select {
	case <-ctx.Done():
		return ErrContextCanceled
	default:
	}

	// Create a result channel to receive the outcome
	resCh := make(chan result, 1)
	t := task{
		fn:     fn,
		result: resCh,
	}

	// Attempt to enqueue the task, respecting context cancellation
	select {
	case p.queue <- t:
		// Successfully enqueued
		return nil
	case <-ctx.Done():
		return ErrContextCanceled
	}
}

// Shutdown initiates graceful shutdown. No new tasks will be accepted.
// Already queued tasks will be processed. Safe to call multiple times.
func (p *Pool) Shutdown() {
	p.closeOnce.Do(func() {
		p.closed.Store(true)
		close(p.queue)
	})
}

// Wait blocks until all workers have exited.
// Must be called after Shutdown to ensure clean termination.
func (p *Pool) Wait() {
	p.wg.Wait()
}

// Stats returns counters for tasks submitted, completed successfully,
// failed with error, and panicked.
func (p *Pool) Stats() (submitted, completed, failed, panicked int) {
	return int(p.submitted.Load()), int(p.completed.Load()), int(p.failed.Load()), int(p.panicked.Load())
}

