/**
 * Strongly typed bounded asynchronous work queue.
 *
 * Public API:
 *   class AsyncWorkQueue<T, R> {
 *     constructor(options: { concurrency: number; capacity: number })
 *     enqueue(task: () => Promise<R>, label?: string): Promise<R>
 *     close(): Promise<void>
 *     get pendingCount(): number
 *     get runningCount(): number
 *     get capacity(): number
 *     get concurrency(): number
 *   }
 *
 * Semantics:
 *   - concurrency: max number of tasks running simultaneously.
 *   - capacity: max number of tasks waiting in the queue (pending).
 *   - enqueue: adds a task. If queue is full (pendingCount >= capacity),
 *     the returned promise rejects with a BackpressureError.
 *   - close: stops accepting new tasks, drains running tasks, rejects
 *     all pending tasks with a ClosedError.
 *   - AbortSignal: if provided via options.signal on enqueue, cancellation
 *     distinguishes:
 *       - pending cancellation: task never started, rejected with AbortError
 *       - running cancellation: task started but aborted mid-execution,
 *         rejected with AbortError
 *   - Ordered result collection: results are collected in enqueue order.
 *   - Graceful drain: close() waits for running tasks to complete.
 *
 * Edge cases handled:
 *   - Zero capacity: enqueue always rejects with BackpressureError.
 *   - Negative capacity: treated as zero.
 *   - Repeated close: subsequent close() calls are no-ops.
 *   - Loader/task failures: task rejections propagate to the caller.
 *   - Canceled waiters: pending tasks with aborted signals are rejected.
 *   - Resources released during cleanup: all internal state is cleared.
 */

// ─── Error Types ────────────────────────────────────────────────────────────

class BackpressureError extends Error {
  constructor(message = "Queue is full") {
    super(message);
    this.name = "BackpressureError";
  }
}

class ClosedError extends Error {
  constructor(message = "Queue is closed") {
    super(message);
    this.name = "ClosedError";
  }
}

class AbortError extends Error {
  constructor(message = "Task was aborted") {
    super(message);
    this.name = "AbortError";
  }
}

// ─── Internal Types ─────────────────────────────────────────────────────────

interface QueueEntry<T, R> {
  task: () => Promise<R>;
  label: string;
  resolve: (value: R) => void;
  reject: (reason: unknown) => void;
  signal?: AbortSignal;
  aborted: boolean;
  started: boolean;
  completed: boolean;
}

interface QueueOptions {
  concurrency: number;
  capacity: number;
}

// ─── AsyncWorkQueue Implementation ──────────────────────────────────────────

class AsyncWorkQueue<T, R> {
  private readonly _concurrency: number;
  private readonly _capacity: number;
  private _pending: QueueEntry<T, R>[] = [];
  private _running: Set<QueueEntry<T, R>> = new Set();
  private _closed: boolean = false;
  private _drainPromise: Promise<void> | null = null;
  private _drainResolve: (() => void) | null = null;
  private _drainReject: ((reason: unknown) => void) | null = null;
  private _allEnqueued: Promise<void> | null = null;
  private _allEnqueuedResolve: (() => void) | null = null;

  constructor(options: QueueOptions) {
    // Normalize: negative or zero capacity means no queueing allowed.
    this._concurrency = Math.max(1, Math.floor(options.concurrency));
    this._capacity = Math.max(0, Math.floor(options.capacity));
  }

  get pendingCount(): number {
    return this._pending.length;
  }

  get runningCount(): number {
    return this._running.size;
  }

  get capacity(): number {
    return this._capacity;
  }

  get concurrency(): number {
    return this._concurrency;
  }

  /**
   * Enqueue a task. Returns a promise that resolves with the task result
   * or rejects with BackpressureError, ClosedError, or AbortError.
   */
  enqueue(task: () => Promise<R>, label: string = "task", signal?: AbortSignal): Promise<R> {
