      return Promise.reject(new BackpressureError());
    }

    // If signal is already aborted, reject immediately.
    if (signal?.aborted) {
      return Promise.reject(new AbortError());
    }

    return new Promise<R>((resolve, reject) => {
      const entry: QueueEntry<T, R> = {
        task,
        label,
        resolve,
        reject,
        signal,
        aborted: false,
        started: false,
        completed: false,
      };

      // Listen for abort on the signal.
      if (signal) {
        const onAbort = () => {
          if (entry.completed) return;
          entry.aborted = true;
          if (!entry.started) {
            // Pending cancellation: remove from queue and reject.
            const idx = this._pending.indexOf(entry);
            if (idx !== -1) {
              this._pending.splice(idx, 1);
            }
            entry.completed = true;
            reject(new AbortError());
          }
