   * Close the queue. Stops accepting new tasks, drains running tasks,
   * and rejects all pending tasks with ClosedError.
   */
  close(): Promise<void> {
    if (this._closed) {
      return this._drainPromise ?? Promise.resolve();
    }
    this._closed = true;

