/// This is O(n) for removals but simple and correct. For production, a doubly-linked list would be better,
/// but we avoid unsafe code and keep it understandable.
struct LruOrder<K> {
    order: Vec<K>,
}

impl<K: Eq + Clone> LruOrder<K> {
    fn new() -> Self {
        LruOrder { order: Vec::new() }
