        let mut current = self.current.lock().unwrap();
        *current = time;
    }
}

impl Default for TestClock {
    fn default() -> Self {
        Self::new()
    }
}

impl Clock for TestClock {
    fn now(&self) -> Duration {
        let current = self.current.lock().unwrap();
        *current
    }
