package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
)

// Task represents a unit of work to be executed by the worker pool.
// The Execute method is called by a worker goroutine. It receives a context
// that is canceled when the pool is shutting down or when the task's context
// is canceled. The Execute method should respect context cancellation.
//
// If Execute panics, the panic is recovered and the error is delivered to the
// result channel.
type Task interface {
	Execute(ctx context.Context) error
}

// TaskFunc is a convenience type that allows a function to implement Task.
type TaskFunc func(ctx context.Context) error

// Execute implements the Task interface.
func (f TaskFunc) Execute(ctx context.Context) error {
	return f(ctx)
}

// Result holds the outcome of a task execution.
type Result struct {
	// Task is the task that was executed.
	Task Task
	// Err is the error returned by the task's Execute method, or nil if
	// the task completed successfully. If the task panicked, Err will be
	// a wrapped error containing the panic value.
	Err error
}

// Pool is a bounded worker pool that executes tasks with backpressure,
// context cancellation, panic recovery, and graceful shutdown.
//
// The pool maintains a fixed number of worker goroutines (up to capacity).
// Tasks are submitted via Submit, which blocks if the internal queue is full
// (backpressure). Results are delivered via the Results channel.
//
// The pool must be closed with Close to release resources. After Close,
// Submit returns ErrPoolClosed.
//
// Concurrency invariants:
// - The number of concurrently executing tasks never exceeds capacity.
// - The internal queue size never exceeds capacity (backpressure).
// - All goroutines are properly terminated on Close.
// - No data races on shared state.
type Pool struct {
	capacity int

	// taskQueue is the channel through which tasks are submitted to workers.
	// Its buffer size equals capacity, providing backpressure.
	taskQueue chan Task

	// results is the channel through which task results are delivered.
	// It is unbuffered; consumers must read from it to avoid blocking workers.
	results chan Result

	// workerWG tracks all worker goroutines.
	workerWG sync.WaitGroup

	// submitWG tracks all pending Submit calls that are blocked on taskQueue.
	// This ensures Close waits for all in-flight submissions to complete.
	submitWG sync.WaitGroup

	// closeOnce ensures Close is idempotent.
	closeOnce sync.Once

	// closed indicates whether the pool has been closed.
	closed atomic.Bool

	// ctx is the context for the pool, used to cancel workers on shutdown.
	ctx    context.Context
	cancel context.CancelFunc

	// mu protects access to closed state checks in Submit.
	mu sync.Mutex
}

// ErrPoolClosed is returned when attempting to submit a task to a closed pool.
var ErrPoolClosed = errors.New("worker pool is closed")

// ErrQueueFull is returned when the task queue is full and the pool is not
// blocking (not used in this implementation, but reserved for future use).
var ErrQueueFull = errors.New("task queue is full")

// New creates a new worker pool with the given capacity.
//
// capacity must be positive. If capacity is zero or negative, it is treated
// as 1 to ensure at least one worker can process tasks.
//
// The pool starts with capacity worker goroutines. Tasks are submitted via
// Submit and results are received from Results.
//
// The caller must call Close when done with the pool to release resources.
func New(capacity int) *Pool {
	if capacity <= 0 {
		capacity = 1
	}

	ctx, cancel := context.WithCancel(context.Background())

	p := &Pool{
		capacity:  capacity,
		taskQueue: make(chan Task, capacity),
		results:   make(chan Result),
		ctx:       ctx,
		cancel:    cancel,
	}

	// Start worker goroutines.
	p.workerWG.Add(capacity)
	for i := 0; i < capacity; i++ {
		go p.worker()
	}

	return p
}

// Submit submits a task to the pool for execution.
//
// If the internal queue is full, Submit blocks until space is available or
// the pool is closed. If the pool is closed, Submit returns ErrPoolClosed.
//
// The task's Execute method will be called by a worker goroutine. The context
// passed to Execute is the pool's context, which is canceled when the pool
// is closed.
//
// Submit is safe for concurrent use.
func (p *Pool) Submit(task Task) error {
	if task == nil {
		return errors.New("task cannot be nil")
	}

	// Check if pool is closed. We use a mutex to ensure we don't submit
	// after Close has started draining.
	p.mu.Lock()
	if p.closed.Load() {
		p.mu.Unlock()
		return ErrPoolClosed
	}
	// Increment submitWG before releasing the lock to ensure Close waits
	// for this submission to complete.
	p.submitWG.Add(1)
	p.mu.Unlock()

	defer p.submitWG.Done()

	// Check again after acquiring the wait group slot, in case Close
	// happened between the check and the Add.
	if p.closed.Load() {
		return ErrPoolClosed
	}

	// Attempt to send the task to the queue. This blocks if the queue is full.
	// We use a select with the pool's context to handle cancellation during
	// blocking send.
	select {
	case p.taskQueue <- task:
		return nil
	case <-p.ctx.Done():
		// Pool is shutting down.
		return ErrPoolClosed
