/**
 * Strongly typed bounded asynchronous work queue.
 *
 * Public API:
 *   class AsyncWorkQueue<T, R> {
 *     constructor(options: AsyncWorkQueueOptions<T, R>)
 *     enqueue(task: T): Promise<R>
 *     close(): Promise<void>
 *     get pendingCount(): number
 *     get runningCount(): number
 *     get capacity(): number
 *   }
 *
 * Options:
 *   concurrency: number - max concurrent running tasks (must be >= 1)
 *   capacity: number - max pending tasks in queue (must be >= 0)
 *   processor: (task: T, signal: AbortSignal) => Promise<R> - async task processor
 *
 * Behavior:
 *   - enqueue() returns a promise that resolves with the result or rejects with the error.
 *   - If the queue is at capacity, enqueue() waits until space is available (backpressure).
 *   - If the queue is closed, enqueue() rejects immediately.
 *   - close() stops accepting new tasks, drains pending tasks, and waits for running tasks.
 *   - AbortSignal cancellation:
 *       - Pending tasks (not yet started) are canceled immediately when their signal aborts.
 *       - Running tasks receive the abort signal; the processor is responsible for honoring it.
 *   - Ordered result collection: results are returned in the order tasks were enqueued.
 *   - Graceful drain: close() waits for all running tasks to complete and processes remaining pending tasks.
 *   - Repeated close() is idempotent.
 *   - Zero capacity: enqueue() blocks until a slot is available (effectively synchronous handoff).
 *   - Negative capacity: throws at construction.
 *   - Loader/task failures: processor errors reject the corresponding enqueue promise.
 *   - Canceled waiters: if an enqueue promise's signal aborts while waiting for capacity, it rejects.
 *   - Resources released during cleanup: all internal state is cleared on close.
 */

import { test } from 'node:test';
import assert from 'node:assert';

// Type definitions

export interface AsyncWorkQueueOptions<T, R> {
  concurrency: number;
  capacity: number;
  processor: (task: T, signal: AbortSignal) => Promise<R>;
}

interface QueuedTask<T, R> {
  task: T;
  resolve: (value: R) => void;
  reject: (reason: unknown) => void;
  signal: AbortSignal;
  aborted: boolean;
  index: number; // for ordered result collection
}

interface RunningTask<T, R> {
  task: T;
  resolve: (value: R) => void;
  reject: (reason: unknown) => void;
  signal: AbortSignal;
  controller: AbortController;
  index: number;
}

export class AsyncWorkQueue<T, R> {
  private readonly concurrency: number;
  private readonly capacity: number;
  private readonly processor: (task: T, signal: AbortSignal) => Promise<R>;

  private pending: QueuedTask<T, R>[] = [];
  private running: RunningTask<T, R>[] = [];
  private closed: boolean = false;
  private closePromise: Promise<void> | null = null;
  private nextIndex: number = 0;

  // For backpressure: waiters waiting for capacity
  private capacityWaiters: Array<{
    resolve: () => void;
    reject: (reason: unknown) => void;
    signal: AbortSignal;
    cleanup: () => void;
  }> = [];

  constructor(options: AsyncWorkQueueOptions<T, R>) {
    if (options.concurrency < 1) {
      throw new Error('concurrency must be >= 1');
    }
    if (options.capacity < 0) {
      throw new Error('capacity must be >= 0');
    }
    if (typeof options.processor !== 'function') {
      throw new Error('processor must be a function');
    }

    this.concurrency = options.concurrency;
    this.capacity = options.capacity;
    this.processor = options.processor;
  }

  get pendingCount(): number {
    return this.pending.length;
  }

  get runningCount(): number {
    return this.running.length;
  }

  get capacity(): number {
    return this.capacity;
  }

  /**
   * Enqueue a task. Returns a promise that resolves with the result or rejects with the error.
   * If the queue is at capacity, this promise waits until space is available.
   * If the queue is closed, this promise rejects immediately.
   * If the provided signal aborts while waiting for capacity, the promise rejects.
   */
  enqueue(task: T, signal?: AbortSignal): Promise<R> {
    if (this.closed) {
      return Promise.reject(new Error('Queue is closed'));
    }

    const index = this.nextIndex++;
    const controller = new AbortController();
    const effectiveSignal = signal ?? controller.signal;

    // If already aborted, reject immediately
    if (effectiveSignal.aborted) {
      return Promise.reject(new Error('Task canceled before enqueue'));
    }

    return new Promise<R>((resolve, reject) => {
      // Check if we can enqueue immediately (not at capacity)
      if (this.pending.length < this.capacity) {
        this._enqueueInternal(task, resolve, reject, effectiveSignal, index);
      } else {
        // Wait for capacity
        const waiter: {
          resolve: () => void;
          reject: (reason: unknown) => void;
          signal: AbortSignal;
          cleanup: () => void;
        } = {
          resolve: () => {
            // Capacity became available, enqueue now
            this._enqueueInternal(task, resolve, reject, effectiveSignal, index);
          },
          reject: (reason: unknown) => {
            reject(reason);
          },
          signal: effectiveSignal,
          cleanup: () => {
            // Remove this waiter from the list
            const idx = this.capacityWaiters.indexOf(waiter);
            if (idx !== -1) {
              this.capacityWaiters.splice(idx, 1);
            }
          },
        };

        this.capacityWaiters.push(waiter);

        // Listen for abort on the signal
        const onAbort = () => {
          waiter.reject(new Error('Task canceled while waiting for capacity'));
          waiter.cleanup();
