/// Internal state of the LRU cache.
struct CacheState<K, V> {
    map: HashMap<K, CacheEntry<V>>,
    // Order of keys from least recently used to most recently used.
    // We use a Vec for simplicity; for production, a linked list would be better.
    lru_order: Vec<K>,
    capacity: usize,
    clock: Arc<dyn Clock>,
}

/// A thread-safe bounded LRU cache with TTL support.
pub struct LruCache<K, V>
where
    K: Clone + Eq + std::hash::Hash + Send + Sync,
    V: Clone + Send + Sync,
{
    state: Arc<Mutex<CacheState<K, V>>>,
}

impl<K, V> LruCache<K, V>
where
    K: Clone + Eq + std::hash::Hash + Send + Sync,
    V: Clone + Send + Sync,
{
