    ///
    /// # Arguments
    /// * `capacity` - Maximum number of entries. If 0, the cache will not store any entries.
    /// * `clock` - Clock implementation for TTL checks.
    pub fn new(capacity: usize, clock: Arc<dyn Clock>) -> Self {
        LruCache {
            state: Arc::new(Mutex::new(CacheState {
                map: HashMap::new(),
                lru_order: Vec::new(),
                capacity,
                clock,
            })),
        }
    }

