// Task represents a unit of work to be executed by the worker pool.
// The Execute function is called with a context that may be canceled during
// shutdown or when the pool is closed.
type Task struct {
	// ID is a unique identifier for the task, useful for debugging and result tracking.
	ID string
	// Execute is the function to run. It receives a context that is canceled
	// when the pool is shutting down or when the task is canceled.
	Execute func(ctx context.Context) (interface{}, error)
}

// Result represents the outcome of a task execution.
type Result struct {
	// TaskID is the ID of the task that produced this result.
	TaskID string
	// Value is the value returned by the task's Execute function.
	Value interface{}
	// Err is the error returned by the task's Execute function, or a pool-level
	// error such as ErrPoolClosed, ErrTaskRejected, or ErrPanic.
	Err error
}

// Pool is a bounded worker pool that executes tasks with concurrency limits,
// supports context cancellation, panic recovery, graceful shutdown, and
// deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int) *Pool: Creates a new pool with the given worker capacity.
//     Capacity must be positive. A capacity of 0 or negative returns an error.
//   - Submit(ctx context.Context, task Task) error: Submits a task to the pool.
//     Returns an error if the pool is closed, the context is canceled, or the
//     task is rejected due to backpressure (if a bounded queue is used).
//     This method blocks until the task is accepted or an error occurs.
//   - Results() <-chan Result: Returns a channel that receives results from completed tasks.
//     The channel is closed when the pool is fully shut down and all results have been delivered.
//   - Shutdown(ctx context.Context) error: Initiates graceful shutdown.
//     No new tasks are accepted. Existing tasks are allowed to complete or are canceled
//     based on the provided context. Returns an error if the context is canceled before
//     shutdown completes.
//   - Close(): Immediately closes the pool, canceling all pending and running tasks.
//     The Results channel will be closed after all in-flight tasks complete.
//
// Concurrency Invariants:
//   - The number of concurrently executing tasks never exceeds the pool capacity.
//   - All submitted tasks are either executed or rejected with a clear error.
//   - Panics in task execution are recovered and reported as errors in the Result.
//   - The Results channel is closed exactly once, after all tasks have completed.
//   - No goroutine leaks: all worker goroutines exit when the pool is closed.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	capacity int

	// taskQueue is a buffered channel that holds tasks waiting to be executed.
	// Its capacity is set to the pool capacity to provide backpressure.
	taskQueue chan Task

	// results is the channel where completed task results are sent.
	results chan Result

	// workers is the number of active worker goroutines.
	workers int

	// mu protects the state fields below.
	mu sync.Mutex

	// closed indicates whether the pool has been closed.
	closed bool

	// shutdownStarted indicates whether shutdown has been initiated.
	shutdownStarted bool

	// wg tracks all active worker goroutines.
	wg sync.WaitGroup

	// ctx is the context for the pool, used to cancel workers during shutdown.
	ctx context.Context
